            int nn = n;
            long ex = 1;
            while (n%10 == 0)
            {
                n /= 10;
                k--;
            }
            while (k > 0)
            {
                if (n%2 == 0)
                {
                    ex *= 5;
                    n /= 2;
                    k--;
                }
                else if (n%5 == 0)
                {
                    ex *= 2;
                    n /= 5;
                    k--;
